const { chromium } = require('./node_modules/playwright')
const path = require('path')

const BASE = 'http://127.0.0.1:8092'
const accounts = [
  { key: 'developer', user: '91320506MA1X901519', pass: 'ZS00001Aa!' },
  { key: 'agency', user: '911255775FXGE322GH', pass: 'ZS0001Aa!' }
]

const outDir = path.resolve(__dirname, 'home-shots')
require('fs').mkdirSync(outDir, { recursive: true })

;(async () => {
  const browser = await chromium.launch({ channel: 'msedge' })
  for (const acc of accounts) {
    const ctx = await browser.newContext({ viewport: { width: 1920, height: 1080 }, deviceScaleFactor: 1 })
    const page = await ctx.newPage()
    const errs = []
    page.on('pageerror', e => errs.push('PAGEERR ' + e.message))
    try {
      await page.goto(BASE + '/#/login', { waitUntil: 'networkidle', timeout: 30000 })
      await page.waitForTimeout(1500)
      // 若不在账号密码页签，切换到密码登录
      const pwdTab = page.locator('.el-tabs__item:has-text("账号密码登录")')
      if (await pwdTab.count()) {
        const cls = await pwdTab.first().getAttribute('class')
        if (!cls || !cls.includes('is-active')) { await pwdTab.first().click(); await page.waitForTimeout(500) }
      }
      const userInput = page.locator('input[placeholder="请输入用户名"]').first()
      const passInput = page.locator('input[placeholder="请输入用户密码"]').first()
      await userInput.waitFor({ timeout: 10000 })
      await userInput.fill(acc.user)
      await passInput.fill(acc.pass)
      await page.locator('.login-button').first().click()
      // 等登录跳转
      await page.waitForTimeout(6000)
      const url = page.url()
      // 等首页数据加载
      await page.waitForTimeout(3500)
      await page.screenshot({ path: path.join(outDir, acc.key + '.png'), fullPage: true })
      await page.screenshot({ path: path.join(outDir, acc.key + '-viewport.png') })
      console.log(`[${acc.key}] afterLoginURL=${url}`)
      if (errs.length) console.log(`[${acc.key}] errors: ${errs.slice(0,3).join(' | ')}`)
    } catch (e) {
      console.log(`[${acc.key}] FAILED: ${e.message}`)
      try { await page.screenshot({ path: path.join(outDir, acc.key + '-fail.png') }) } catch {}
    }
    await ctx.close()
  }
  await browser.close()
})()

